ALTER TABLE plans ADD COLUMN catalog_mode TEXT NOT NULL DEFAULT 'unapproved' CHECK(catalog_mode IN ('unapproved','demo','official'));
ALTER TABLE plans ADD COLUMN catalog_version INTEGER NOT NULL DEFAULT 1;
ALTER TABLE plans ADD COLUMN approved_at TEXT;
ALTER TABLE plans ADD COLUMN approved_by TEXT REFERENCES users(id);
UPDATE plans SET catalog_mode='demo' WHERE id IN ('b92c1c4e-0679-42bc-9ad0-de369b2d8fb4','dc591d2a-b7ea-492c-a5da-2199b41378fb','8bd1a011-646c-4be2-aabc-feebdc00b52d');
ALTER TABLE orders ADD COLUMN payment_environment TEXT NOT NULL DEFAULT 'unbound' CHECK(payment_environment IN ('unbound','test','live'));
ALTER TABLE orders ADD COLUMN refunded_minor INTEGER NOT NULL DEFAULT 0 CHECK(refunded_minor>=0);
ALTER TABLE billing_risks ADD COLUMN resolved_at TEXT;
ALTER TABLE billing_risks ADD COLUMN resolved_by TEXT REFERENCES users(id);
ALTER TABLE billing_risks ADD COLUMN resolution_reason TEXT;
ALTER TABLE billing_risks ADD COLUMN evidence_reference TEXT;
ALTER TABLE billing_risks ADD COLUMN referral_reward_id TEXT;
CREATE TABLE operator_audit(id TEXT PRIMARY KEY,actor_user_id TEXT NOT NULL REFERENCES users(id),action TEXT NOT NULL,reason TEXT NOT NULL,evidence_reference TEXT,details_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE invoice_events(id TEXT PRIMARY KEY,invoice_id TEXT NOT NULL REFERENCES invoice_requests(id),actor_user_id TEXT REFERENCES users(id),kind TEXT NOT NULL,details_json TEXT NOT NULL,created_at TEXT NOT NULL);
ALTER TABLE invoice_orders ADD COLUMN amount_minor INTEGER;
UPDATE invoice_orders SET amount_minor=(SELECT amount_minor FROM orders WHERE orders.id=invoice_orders.order_id);
ALTER TABLE character_profiles ADD COLUMN reference_revision INTEGER NOT NULL DEFAULT 1;
CREATE TABLE character_authorizations(id TEXT PRIMARY KEY,character_id TEXT NOT NULL REFERENCES character_profiles(id),workspace_id TEXT NOT NULL REFERENCES workspaces(id),reference_revision INTEGER NOT NULL,asset_ids_json TEXT NOT NULL,statement_version TEXT NOT NULL,subject_relationship TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('active','withdrawn','stale')),authorized_by TEXT NOT NULL REFERENCES users(id),authorized_at TEXT NOT NULL,withdrawn_at TEXT,withdrawal_reason TEXT);
CREATE INDEX character_authorizations_latest ON character_authorizations(character_id,authorized_at DESC,id);
CREATE UNIQUE INDEX character_authorizations_active ON character_authorizations(character_id) WHERE status='active';
CREATE TABLE identity_sessions(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),character_id TEXT NOT NULL REFERENCES character_profiles(id),reference_revision INTEGER NOT NULL,provider_id TEXT NOT NULL,provider_session_id TEXT NOT NULL,verification_url TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('processing','failed','expired','active','withdrawn')),evidence_reference TEXT,expires_at TEXT NOT NULL,error_message TEXT,created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE referral_program(id TEXT PRIMARY KEY CHECK(id='default'),registration_enabled INTEGER NOT NULL DEFAULT 0,rewards_enabled INTEGER NOT NULL DEFAULT 0,reward_credits INTEGER NOT NULL DEFAULT 0,minimum_paid_minor INTEGER NOT NULL DEFAULT 1,currency TEXT NOT NULL DEFAULT 'USD',version INTEGER NOT NULL DEFAULT 1,updated_by TEXT REFERENCES users(id),updated_at TEXT NOT NULL);
INSERT INTO referral_program(id,updated_at) VALUES('default',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
CREATE TABLE referral_attributions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL UNIQUE REFERENCES users(id),referral_id TEXT NOT NULL REFERENCES referrals(id),program_snapshot_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE referral_rewards(id TEXT PRIMARY KEY,attribution_id TEXT NOT NULL UNIQUE REFERENCES referral_attributions(id),qualifying_order_id TEXT NOT NULL UNIQUE REFERENCES orders(id),reward_workspace_id TEXT NOT NULL REFERENCES workspaces(id),reward_user_id TEXT NOT NULL REFERENCES users(id),credits INTEGER NOT NULL CHECK(credits>=0),reversed_credits INTEGER NOT NULL DEFAULT 0,debt_credits INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE channel_partners(user_id TEXT PRIMARY KEY REFERENCES users(id),enabled INTEGER NOT NULL DEFAULT 1,approved_by TEXT NOT NULL REFERENCES users(id),reason TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
ALTER TABLE invoice_orders RENAME TO invoice_orders_legacy;
CREATE TABLE invoice_orders(invoice_id TEXT NOT NULL REFERENCES invoice_requests(id),order_id TEXT NOT NULL REFERENCES orders(id),amount_minor INTEGER NOT NULL CHECK(amount_minor>0),released_at TEXT,PRIMARY KEY(invoice_id,order_id));
INSERT INTO invoice_orders(invoice_id,order_id,amount_minor) SELECT invoice_id,order_id,amount_minor FROM invoice_orders_legacy;
DROP TABLE invoice_orders_legacy;
CREATE UNIQUE INDEX invoice_orders_active ON invoice_orders(order_id) WHERE released_at IS NULL;
